<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue'; import { useRouter } from 'vue-router';
import Button from 'primevue/button'; import Select from 'primevue/select'; import Chart from 'primevue/chart';
import { api, downloadCsv, currentUser } from '../lib/api'; import { money, number, date, type Data, type Ride } from '../lib/types'; import { useQuery } from '../composables/useQuery';
import { canAccess } from '../lib/access';
import QueryState from '../components/QueryState.vue'; import OperationsMap from '../components/OperationsMap.vue'; import RideTable from '../components/RideTable.vue';
const router = useRouter(), period = ref(7), mapFilter = ref('ALL');
const { data, loading, error, refresh } = useQuery(() => api('/admin/dashboard?days=' + period.value), 15000);
const rides = useQuery(() => canAccess('/rides', currentUser.value?.role) ? api<{ items: Ride[] }>('/admin/rides?pageSize=6') : Promise.resolve({items: [] as Ride[]}), 15000); const drivers = useQuery(() => canAccess('/drivers', currentUser.value?.role) ? api('/admin/drivers') : Promise.resolve({items: []}), 15000);
const mapDrivers = computed(() => (drivers.data.value?.items ?? []).filter((d: Data) => mapFilter.value === 'ALL' || d.serviceTypeCode === mapFilter.value));
const chartData = computed(() => ({ labels: data.value?.chart.map((d: Data) => d.date.slice(8) + '/' + d.date.slice(5, 7)) ?? [], datasets: [{ label: 'Giá gộp chuyến', data: data.value?.chart.map((d: Data) => d.grossFare) ?? [], borderColor: '#159367', backgroundColor: 'rgba(21,147,103,.07)', fill: true, tension: .38, borderWidth: 2.5, pointRadius: 3, pointBackgroundColor: '#fff', pointBorderWidth: 2 }, { label: 'Phí nền tảng', data: data.value?.chart.map((d: Data) => d.platformFees) ?? [], borderColor: '#9db8ef', borderDash: [5, 5], tension: .38, borderWidth: 2, pointRadius: 0 }] }));
const chartOptions = { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false }, tooltip: { callbacks: { label: (ctx: Data) => ctx.dataset.label + ': ' + money(ctx.parsed.y) } } }, scales: { x: { grid: { display: false }, border: { display: false }, ticks: { color: '#8b93a3', font: { size: 11 } } }, y: { border: { display: false, dash: [4, 4] }, grid: { color: '#eef1f4' }, ticks: { color: '#8b93a3', font: { size: 11 }, callback: (v: number | string) => Number(v) >= 1000000 ? Number(v) / 1000000 + ' tr' : Number(v) / 1000 + 'k' } } } };
const total = computed(() => data.value?.chart.reduce((sum: number, item: Data) => sum + item.grossFare, 0) ?? 0);
const firstName = computed(() => currentUser.value?.name.split(' ').slice(-2).join(' '));
function changeRate(today: number, yesterday: number) { return yesterday > 0 ? ((today - yesterday) / yesterday * 100).toFixed(1) + '%' : 'Chưa có kỳ so sánh'; }
function exportReport() { downloadCsv('grap-bao-cao-van-hanh.csv', data.value?.chart ?? [], { date: 'Ngày', rides: 'Số chuyến', grossFare: 'Giá gộp (VND)', platformFees: 'Phí nền tảng (VND)' }); }
function reload() { void refresh(); void rides.refresh(); void drivers.refresh(); } onMounted(() => window.addEventListener('grap:refresh', reload)); onUnmounted(() => window.removeEventListener('grap:refresh', reload));
</script>
<template><div class="page-heading"><div><div class="eyebrow">TRUNG TÂM ĐIỀU HÀNH</div><h1>Tổng quan vận hành<span class="green-text">.</span></h1><p>Mọi chuyển động của nền tảng, trong một góc nhìn.</p></div><div class="heading-actions"><span class="date-pill"><i class="pi pi-calendar"></i>{{ date(new Date(), false) }}</span><Button label="Xuất báo cáo" icon="pi pi-download" severity="secondary" outlined :disabled="!data" @click="exportReport"/></div></div>
<QueryState :loading="loading" :error="error" @retry="refresh"/>
<template v-if="data"><div class="welcome-banner"><div><span class="welcome-badge"><span class="green-dot"></span> WORKSPACE · HỒ CHÍ MINH</span><h2>Chào {{ firstName }}, một ngày mới tốt lành!</h2><p>Cùng kết nối những hành trình an toàn và thuận tiện cho thành phố.</p></div><div class="welcome-stat"><span>CHUYẾN ĐANG HOẠT ĐỘNG</span><strong>{{ number(data.activeRides) }}<i class="pi pi-arrow-up-right"></i></strong><RouterLink v-if="canAccess('/dispatch', currentUser?.role)" to="/dispatch">Đến trang điều phối <i class="pi pi-arrow-right"></i></RouterLink></div><div class="banner-decoration"><i class="pi pi-directions-alt"></i></div></div>
<div class="metric-grid"><div class="metric-card"><div class="metric-top"><span>Tổng chuyến hôm nay</span><span class="metric-icon green"><i class="pi pi-directions-alt"></i></span></div><div class="metric-value">{{ number(data.today.rides) }}<span>chuyến</span><svg viewBox="0 0 100 34" class="sparkline" aria-hidden="true"><path d="M2 29L15 21L27 25L39 16L51 19L63 9L75 13L87 6L98 2"/></svg></div><div class="metric-foot"><span class="change" :class="{ negative: data.today.rides < data.yesterday.rides }"><i class="pi" :class="data.today.rides < data.yesterday.rides ? 'pi-arrow-down-right' : 'pi-arrow-up-right'"></i>{{ changeRate(data.today.rides, data.yesterday.rides) }}</span><span>so với hôm qua</span></div></div><div class="metric-card"><div class="metric-top"><span>Giá gộp chuyến hôm nay</span><span class="metric-icon blue"><i class="pi pi-wallet"></i></span></div><div class="metric-value compact-number">{{ money(data.today.grossFare) }}</div><div class="metric-foot"><span class="change" :class="{ negative: data.today.grossFare < data.yesterday.grossFare }">{{ changeRate(data.today.grossFare, data.yesterday.grossFare) }}</span><span>so với hôm qua</span></div></div><div class="metric-card"><div class="metric-top"><span>Tài xế sẵn sàng</span><span class="metric-icon purple"><i class="pi pi-id-card"></i></span></div><div class="metric-value">{{ number(data.today.onlineDrivers) }}<span>tài xế</span><div class="mini-bars"><i v-for="n in 10" :key="n" :style="{ height: (12 + n * 2) + 'px', opacity: .2 + n * .07 }"></i></div></div><div class="metric-foot"><span class="green-dot"></span><span>GPS & heartbeat mới trong 30 giây</span></div></div><div class="metric-card"><div class="metric-top"><span>Tỷ lệ hoàn thành hôm nay</span><span class="metric-icon orange"><i class="pi pi-check-circle"></i></span></div><div class="metric-value">{{ data.today.successRate }}<span>%</span></div><div class="metric-foot"><div class="metric-progress"><span :style="{ width: data.today.successRate + '%' }"></span></div><span>{{ data.today.completed }}/{{ data.today.rides }} chuyến</span></div></div></div>
<div class="dashboard-main-grid"><section class="panel revenue-panel"><div class="panel-header"><div><h2>Hiệu quả hoạt động <span class="info-circle" v-tooltip="'Giá gộp chuyến hoàn tất, không phải doanh thu kế toán'"><i class="pi pi-info-circle"></i></span></h2><p>Giá trị các hành trình đã hoàn thành</p></div><Select v-model="period" :options="[{ label: '7 ngày gần nhất', value: 7 }, { label: '14 ngày gần nhất', value: 14 }, { label: '30 ngày gần nhất', value: 30 }]" option-label="label" option-value="value" size="small" @change="refresh"/></div><div class="revenue-total"><strong>{{ money(total) }}</strong><span class="muted">trong {{ period }} ngày</span></div><div class="chart-legend"><span><i class="legend-dot emerald"></i>Giá gộp chuyến</span><span><i class="legend-dot blue"></i>Phí nền tảng</span></div><div class="revenue-chart"><Chart type="line" :data="chartData" :options="chartOptions"/></div></section><section class="panel attention-panel"><div class="panel-header"><div><h2>Cần bạn chú ý</h2><p>Những việc đang chờ xử lý</p></div><span class="attention-bell"><i class="pi pi-bell"></i></span></div><RouterLink v-if="canAccess('/drivers', currentUser?.role)" to="/drivers?status=PENDING_REVIEW" class="attention-row"><span class="attention-icon orange"><i class="pi pi-id-card"></i></span><div><strong>Hồ sơ tài xế chờ duyệt</strong><span>Đối tác mới đang chờ gia nhập</span></div><b>{{ data.pendingDrivers }}</b><i class="pi pi-angle-right"></i></RouterLink><RouterLink v-if="canAccess('/support', currentUser?.role)" to="/support" class="attention-row"><span class="attention-icon blue"><i class="pi pi-comments"></i></span><div><strong>Yêu cầu hỗ trợ</strong><span>Cần tiếp nhận và phản hồi</span></div><b>{{ data.openTickets }}</b><i class="pi pi-angle-right"></i></RouterLink><RouterLink v-if="canAccess('/finance', currentUser?.role)" to="/finance" class="attention-row"><span class="attention-icon rose"><i class="pi pi-credit-card"></i></span><div><strong>Khoản thu cần kiểm tra</strong><span>Tiền mặt chưa được thu đủ</span></div><b>{{ data.paymentIssues }}</b><i class="pi pi-angle-right"></i></RouterLink><div class="operations-note"><i class="pi pi-shield"></i><div><strong>Vận hành minh bạch, an toàn</strong><p>Dữ liệu chuyến, thanh toán và đối soát có vòng đời độc lập.</p></div></div></section></div>
<section v-if="canAccess('/drivers', currentUser?.role)" class="panel map-panel"><div class="panel-header"><div class="title-with-icon"><span class="panel-title-icon"><i class="pi pi-map"></i></span><div><h2>Toàn cảnh khu vực hoạt động <span class="live-pill"><span></span>{{ data.today.onlineDrivers }} sẵn sàng</span></h2><p>Vị trí gần nhất của tài xế trong vùng phục vụ</p></div></div><div class="segmented"><button v-for="(label, value) in { ALL: 'Tất cả', BIKE: 'Xe máy', CAR_4: 'Ô tô 4 chỗ', CAR_7: 'Ô tô 7 chỗ' }" :key="value" :class="{ active: mapFilter === value }" @click="mapFilter = value">{{ label }}</button></div></div><QueryState :loading="drivers.loading.value" :error="drivers.error.value" @retry="drivers.refresh"/><OperationsMap :drivers="mapDrivers"/><div class="map-footer"><span><i class="legend-dot emerald"></i>Vị trí mới</span><span><i class="legend-dot grey"></i>Vị trí cũ / ngoại tuyến</span><span class="map-footer-right"><i class="pi pi-info-circle"></i> Không tự kết thúc chuyến khi mất GPS</span></div></section>
<section v-if="canAccess('/rides', currentUser?.role)" class="panel"><div class="panel-header"><div><h2>Chuyến xe gần đây</h2><p>Những hành trình mới nhất trên nền tảng</p></div><Button label="Xem tất cả chuyến" icon="pi pi-arrow-right" icon-pos="right" text size="small" @click="router.push('/rides')"/></div><QueryState :loading="rides.loading.value" :error="rides.error.value" @retry="rides.refresh"/><RideTable v-if="rides.data.value" :rides="rides.data.value.items" @select="r => router.push('/rides?id=' + r.rideId)"/></section><div class="last-updated"><i class="pi pi-sync"></i> Cập nhật {{ date(data.serverTime) }} · Tự làm mới mỗi 15 giây</div></template></template>
